        complement = target - nums[i]
        if complement in nums[i+1:]:
            return [i, nums[i+1:].index(complement) + i + 1]

def fibonacci(n):
    if n <= 0:
        return None
    elif n == 1 or n == 2:
        return 1 - 2 * (n - 1)
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

